INSERT INTO "policycontent" ("id", "Type_id", "Locale_Code", "Content", "createdby", "modifiedby", "softdeleteflag", "companyLegalUnit")VALUES  ('POL1','PT_CUST_USERNAME','en-US','<ul class="\&#34;\&#34;"><li class="\&#34;\&#34;">The username should contain atleast 8 characters and atmost 64 characters.</li><li class="\&#34;\&#34;">Must contain at least one special character. Only (&#39;.&#39;,&#39;-&#39;,&#39;_&#39;,&#39;&#64;&#39;,&#39;!&#39;,&#39;#&#39;,&#39;$&#39;) characters are allowed.</li><li class="\&#34;\&#34;">The username cannot contain the same consecutive special character</li><li class="\&#34;\&#34;">The first character of the username must be an ascii letter (a-z) or number (0-9)</li><li class="\&#34;\&#34;">The last character of the username must be an ascii letter (a-z) or number (0-9)</li></ul>','Kony User','UID10',0,'ALL');
INSERT INTO "policycontent" ("id", "Type_id", "Locale_Code", "Content", "createdby", "modifiedby", "softdeleteflag", "companyLegalUnit")VALUES ('POL2','PT_CUST_PASSWORD','en-US','<ul class=""><li class="">The password should contain at least 8 characters and up to 64 characters</li><li class="">Must contain at least one special character, only the following are allowed: .-_@!#$</li><li class="">Password must contain at least one uppercase, one lowercase, and one number</li><li class="">Password can have up to 4 consecutive repeated characters</li></ul>','Kony User','Kony Dev',0,'ALL');
